def _status_fa(module: str, v: dict) -> str:
    import shared_controls as sc
    try:
        st = sc.lowtf_status(module, {sc_vkey(module): v}) if v else "NA"
    except Exception:  # noqa: BLE001
        st = "NA"
    return {"PASS": "🟢 PASS — همه‌ی دروازه‌های سخت‌گیرانه را پاس کرد",
            "CAND": "🟡 کاندید سودده — سود معنادار و پایدار دارد ولی از دروازه‌ی کامل PASS کمی ضعیف‌تر است؛ فعال است و ادمین می‌تواند خاموشش کند",
            "FAIL": "🔴 قفل — سود معنادار و پایدار ثابت نشده؛ با نتیجه‌ی بعدیِ آزمایشگاه خودکار دوباره سنجیده می‌شود",
            "NA": "⚪ هنوز بک‌تست نشده"}.get(st, st)


def sc_vkey(module: str) -> str:
    import ladder_catalog as lc
    return lc.vkey(module)


def verdict_card(module: str, v: dict) -> str:
    """کارت نتیجه‌ی آزمایشگاه: وضعیت، بهترین تایم‌فریم/فیلتر/حد ضرر، نردبان پیشنهادی با آمار خودش، و علت‌های PASS‌نشدن به زبان ساده."""
    import ladder_catalog as lc
    if not v:
        return "📊 نتیجه‌ی آزمایشگاه: هنوز موجود نیست."
    out = [f"📊 <b>نتیجه‌ی آزمایشگاه</b>", f"وضعیت: {_status_fa(module, v)}"]
    out.append(f"بهترین ترکیب: تایم‌فریم {str(v.get('tf', '?')).upper()} · فیلتر «{FILTERS.get(v.get('filter', 'none'), v.get('filter'))}» · {STOPS.get(v.get('stop', 'nat'), v.get('stop'))}")
    try:
        r = [(k, x) for k, x in lc.rank_ladders(v.get("stats")) if len(lc.LADDERS[k][0]) >= 2 or x.get("sem") == "live4"]
    except Exception:  # noqa: BLE001
        r = []
    if r:
        k, x = r[0]
        out.append(f"🪜 نردبان پیشنهادی: <b>{k}</b> — {lc.describe(k)}")
        out.append(f"   میانگین {x.get('avg', 0):+.3f}R/معامله (بعد از کارمزد) · t={x.get('t', 0):.1f} · وین‌ریت {x.get('win', 0):.0f}% · PF {x.get('pf', 0):.2f} · "
                   f"train {x.get('train', 0):+.2f}R / test {x.get('test', 0):+.2f}R")
    out.append(f"حجم نمونه: {v.get('n', 0)} معامله · نمادهای مثبت {(v.get('symbols_positive') or 0) * 100:.0f}% · بیشینه دراودان {v.get('max_dd_r', 0):.0f}R")
    rs = [x for x in (v.get("fail_reasons") or []) if x]
    if rs:
        out.append("چرا PASS کامل نشد: " + "؛ ".join(_REASON_FA.get(x, x) for x in rs) + ".")
    out.append("راهنما: t≥۴ یعنی لبه‌ی واقعی (نه شانس)؛ PF = جمع سودها ÷ جمع زیان‌ها؛ train/test = عملکرد دوره‌ی اول/دوم داده (هر دو باید مثبت باشند).")
    return "\n".join(out)


def describe(module: str, verdict: dict = None, cfg_line: str = "") -> str:
    """متن کامل توضیح استراتژی + کارت نتیجه‌ی آزمایشگاه (خودکار از lowtf_verdicts.json)."""
    import ladder_catalog as lc
    if module in lc.CANDLE:
        d = _CN
    else:
        d = DESC.get(module, "")
    out = [d]
    v = verdict or {}
    if v:
        out.append("")
        out.append(verdict_card(module, v))
    if cfg_line:
        out.append("")
        out.append(cfg_line)
    return "\n".join(x for x in out if x is not None)
